import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, color } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3, Euler } = ctx.THREE;

  const group = new Group();
  group.userData.cleanup = () => {
    // No timelines or async loaders to clean up
  };

  // Create plane geometry (default unit square)
  const geometry = new PlaneGeometry(1, 1);

  // Load the texture via ctx.textureLoader
  ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    // Create material with the loaded texture
    const uvNode = uv();
    const material = new MeshBasicNodeMaterial({
      colorNode: color(texture),
      map: texture,
      transparent: true,
    });

    // Create mesh
    const mesh = new Mesh(geometry, material);

    // Apply position from config
    if (config.scenePosition) {
      mesh.position.copy(new Vector3(...config.scenePosition));
    }

    // Apply rotation from config (if present)
    if (config.sceneRotation) {
      mesh.rotation.copy(new Euler(...config.sceneRotation));
    }

    // Apply scale from config (if present)
    if (config.sceneScale) {
      mesh.scale.copy(new Vector3(...config.sceneScale));
    }

    group.add(mesh);
  });

  // Render text content: "Features 2" as headline
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  for (const item of textItems) {
    if (item.text && item.role === 'headline') {
      const textMesh = ctx.fontAtlas.createText(item.text, {
        fontSize: item.typography?.fontSize ?? 39,
        color: config.intent?.visualSpec?.colors?.ink ?? '#16161d',
        align: 'center',
      });

      // Position text above/below the plane, slightly offset in z
      textMesh.position.z = 0.2;
      textMesh.position.y = 0.6;
      group.add(textMesh);
    }
  }

  return group;
}
